"""Copy the slide renderer out of the engine page so automated exports match the page exactly.

The engine page (engine/lock-in-engine.html) is the source of truth. Run this after changing it:
    python3 tools/extract_renderer.py
"""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
src = (root / "engine" / "lock-in-engine.html").read_text()


def between(start, end):
    i = src.index(start)
    j = src.index(end, i)
    return src[i:j]


parts = [
    "// GENERATED by tools/extract_renderer.py from engine/lock-in-engine.html. Do not edit.",
    between("// Slide looks:", "const DEFAULT_SETTINGS"),
    "const pad = n => String(n).padStart(2, \"0\");",
    between("const W = 1080, H = 1350, M = 96;", "async function drawPreviews()"),
]
(root / "render" / "slides.generated.js").write_text("\n".join(parts))
print("wrote render/slides.generated.js")
